namespace sv_3e2cf7013e554d3f832c448327b3282e.Client.Models;

public record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTime EstimatedDelivery,
    List<StatusUpdate> StatusUpdates);

public record StatusUpdate(
    string Description,
    string Location,
    DateTime Timestamp);

using sv_3e2cf7013e554d3f832c448327b3282e.Client.Models;

namespace sv_3e2cf7013e554d3f832c448327b3282e.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_3e2cf7013e554d3f832c448327b3282e.Client.Models;
using sv_3e2cf7013e554d3f832c448327b3282e.Client.Services;

namespace sv_3e2cf7013e554d3f832c448327b3282e.Services;

public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new ShipmentDetails(
            "TRK-001",
            "In Transit",
            "Chicago, IL",
            new DateTime(2026, 6, 20, 17, 0, 0, DateTimeKind.Utc),
            new List<StatusUpdate>
            {
                new("Package picked up", "New York, NY", new DateTime(2026, 6, 14, 9, 0, 0, DateTimeKind.Utc)),
                new("Departed facility", "New York, NY", new DateTime(2026, 6, 14, 14, 30, 0, DateTimeKind.Utc)),
                new("Arrived at sorting center", "Chicago, IL", new DateTime(2026, 6, 15, 6, 0, 0, DateTimeKind.Utc)),
            }),
        ["TRK-002"] = new ShipmentDetails(
            "TRK-002",
            "Delivered",
            "San Francisco, CA",
            new DateTime(2026, 6, 15, 12, 0, 0, DateTimeKind.Utc),
            new List<StatusUpdate>
            {
                new("Package picked up", "Seattle, WA", new DateTime(2026, 6, 12, 10, 0, 0, DateTimeKind.Utc)),
                new("In transit", "Portland, OR", new DateTime(2026, 6, 13, 8, 0, 0, DateTimeKind.Utc)),
                new("Out for delivery", "San Francisco, CA", new DateTime(2026, 6, 14, 7, 0, 0, DateTimeKind.Utc)),
                new("Delivered", "San Francisco, CA", new DateTime(2026, 6, 14, 14, 22, 0, DateTimeKind.Utc)),
            }),
        ["TRK-003"] = new ShipmentDetails(
            "TRK-003",
            "Processing",
            "Dallas, TX",
            new DateTime(2026, 6, 22, 18, 0, 0, DateTimeKind.Utc),
            new List<StatusUpdate>
            {
                new("Label created", "Dallas, TX", new DateTime(2026, 6, 16, 8, 0, 0, DateTimeKind.Utc)),
            }),
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

using System.Net.Http.Json;
using sv_3e2cf7013e554d3f832c448327b3282e.Client.Models;

namespace sv_3e2cf7013e554d3f832c448327b3282e.Client.Services;

public class ShipmentServiceHttpClient : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentServiceHttpClient(HttpClient http)
    {
        _http = http;
    }

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await _http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct);
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_3e2cf7013e554d3f832c448327b3282e.Client.Models
@using sv_3e2cf7013e554d3f832c448327b3282e.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<Shipment> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p>Loading shipment details for <strong>@TrackingNumber</strong>...</p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="error-container">
        <p class="error-message">@_errorMessage</p>
        <button @onclick="RetryLoad">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="not-found">
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <div class="shipment-details">
        <h2>Shipment @_shipment.TrackingNumber</h2>
        <dl>
            <dt>Status</dt>
            <dd>@_shipment.Status</dd>
            <dt>Location</dt>
            <dd>@_shipment.Location</dd>
            <dt>Estimated Delivery</dt>
            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
        </dl>

        <h3>Status Updates</h3>
        @if (_shipment.StatusUpdates.Count == 0)
        {
            <p>No status updates available.</p>
        }
        else
        {
            <ul class="status-updates">
                @foreach (var update in _shipment.StatusUpdates.OrderByDescending(u => u.Timestamp))
                {
                    <li>
                        <strong>@update.Timestamp.ToString("g")</strong> —
                        @update.Description (@update.Location)
                    </li>
                }
            </ul>
        }
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private ShipmentDetails? _shipment;
    private bool _loading = true;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any previous in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _loading = true;
        _errorMessage = null;
        _shipment = null;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed; do nothing.
            return;
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException || ex.CancellationToken != ct)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryLoad()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

